123     }
124 
126     aiQuatKey(double time, const aiQuaternion &value) :
127             mTime(time), mValue(value) {}
128 
129     typedef aiQuaternion elem_type;
130 
131     // Comparison operators. For use with std::find();
132     bool operator==(const aiQuatKey &rhs) const {
133         return rhs.mValue == this->mValue;
134     }
135     
136     bool operator!=(const aiQuatKey &rhs) const {
137         return rhs.mValue != this->mValue;
138     }
139 
140     // Relational operators. For use with std::sort();
141     bool operator<(const aiQuatKey &rhs) const {
142         return mTime < rhs.mTime;
143     }
144     
145     bool operator>(const aiQuatKey &rhs) const {
146         return mTime > rhs.mTime;
147     }
148 #endif
149 };
