153 struct aiMeshKey {
155     double mTime;
156 
161     unsigned int mValue;
162 
163 #ifdef __cplusplus
164 
165     aiMeshKey() AI_NO_EXCEPT
166             : mTime(0.0),
167               mValue(0) {
168     }
169 
171     aiMeshKey(double time, const unsigned int value) :
172             mTime(time), mValue(value) {}
173 
174     typedef unsigned int elem_type;
175 
176     // Comparison operators. For use with std::find();
177     bool operator==(const aiMeshKey &o) const {
178         return o.mValue == this->mValue;
179     }
180     bool operator!=(const aiMeshKey &o) const {
181         return o.mValue != this->mValue;
182     }
183 
184     // Relational operators. For use with std::sort();
185     bool operator<(const aiMeshKey &o) const {
186         return mTime < o.mTime;
187     }
188     bool operator>(const aiMeshKey &o) const {
189         return mTime > o.mTime;
190     }
191 
192 #endif
193 };
