197 struct aiMeshMorphKey {
199     double mTime;
200 
202     unsigned int *mValues;
203     double *mWeights;
204 
206     unsigned int mNumValuesAndWeights;
207 #ifdef __cplusplus
208     aiMeshMorphKey() AI_NO_EXCEPT
209             : mTime(0.0),
210               mValues(nullptr),
211               mWeights(nullptr),
212               mNumValuesAndWeights(0) {
213     }
214 
215     ~aiMeshMorphKey() {
216         if (mNumValuesAndWeights && mValues && mWeights) {
217             delete[] mValues;
218             delete[] mWeights;
219         }
220     }
221 #endif
222 };
