267 struct aiNodeAnim {
270     C_STRUCT aiString mNodeName;
271 
273     unsigned int mNumPositionKeys;
274 
280     C_STRUCT aiVectorKey *mPositionKeys;
281 
283     unsigned int mNumRotationKeys;
284 
291     C_STRUCT aiQuatKey *mRotationKeys;
292 
294     unsigned int mNumScalingKeys;
295 
301     C_STRUCT aiVectorKey *mScalingKeys;
302 
308     C_ENUM aiAnimBehaviour mPreState;
309 
315     C_ENUM aiAnimBehaviour mPostState;
316 
317 #ifdef __cplusplus
318     aiNodeAnim() AI_NO_EXCEPT
319             : mNumPositionKeys(0),
320               mPositionKeys(nullptr),
321               mNumRotationKeys(0),
322               mRotationKeys(nullptr),
323               mNumScalingKeys(0),
324               mScalingKeys(nullptr),
325               mPreState(aiAnimBehaviour_DEFAULT),
326               mPostState(aiAnimBehaviour_DEFAULT) {
327         // empty
328     }
329 
330     ~aiNodeAnim() {
331         delete[] mPositionKeys;
332         delete[] mRotationKeys;
333         delete[] mScalingKeys;
334     }
335 #endif // __cplusplus
336 };
