398 // ---------------------------------------------------------------------------
401 struct aiAnimation {
405     C_STRUCT aiString mName;
406 
408     double mDuration;
409 
411     double mTicksPerSecond;
412 
415     unsigned int mNumChannels;
416 
419     C_STRUCT aiNodeAnim **mChannels;
420 
423     unsigned int mNumMeshChannels;
424 
427     C_STRUCT aiMeshAnim **mMeshChannels;
428 
431     unsigned int mNumMorphMeshChannels;
432 
435     C_STRUCT aiMeshMorphAnim **mMorphMeshChannels;
436 
437 #ifdef __cplusplus
438     aiAnimation() AI_NO_EXCEPT
439             : mDuration(-1.),
440               mTicksPerSecond(0.),
441               mNumChannels(0),
442               mChannels(nullptr),
443               mNumMeshChannels(0),
444               mMeshChannels(nullptr),
445               mNumMorphMeshChannels(0),
446               mMorphMeshChannels(nullptr) {
447         // empty
448     }
449 
450     ~aiAnimation() {
451         // DO NOT REMOVE THIS ADDITIONAL CHECK
452         if (mNumChannels && mChannels) {
453             for (unsigned int a = 0; a < mNumChannels; a++) {
454                 delete mChannels[a];
455             }
456 
457             delete[] mChannels;
458         }
459         if (mNumMeshChannels && mMeshChannels) {
460             for (unsigned int a = 0; a < mNumMeshChannels; a++) {
461                 delete mMeshChannels[a];
462             }
463 
464             delete[] mMeshChannels;
465         }
466         if (mNumMorphMeshChannels && mMorphMeshChannels) {
467             for (unsigned int a = 0; a < mNumMorphMeshChannels; a++) {
468                 delete mMorphMeshChannels[a];
469             }
470 
471             delete[] mMorphMeshChannels;
472         }
473     }
474 #endif // __cplusplus
475 };
