481 namespace Assimp {
482 
483 // ---------------------------------------------------------------------------
490 template <typename T>
491 struct Interpolator {
492     // ------------------------------------------------------------------
498     void operator()(T &anim_out, const T &a, const T &b, ai_real d) const {
499         anim_out = a + (b - a) * d;
500     }
501 }; // ! Interpolator <T>
502 
504 
505 template <>
506 struct Interpolator<aiQuaternion> {
507     void operator()(aiQuaternion &out, const aiQuaternion &a,
508             const aiQuaternion &b, ai_real d) const {
509         aiQuaternion::Interpolate(out, a, b, d);
510     }
511 }; // ! Interpolator <aiQuaternion>
512 
513 template <>
514 struct Interpolator<unsigned int> {
515     void operator()(unsigned int &out, unsigned int a,
516             unsigned int b, ai_real d) const {
517         out = d > 0.5f ? b : a;
518     }
519 }; // ! Interpolator <aiQuaternion>
520 
521 template <>
522 struct Interpolator<aiVectorKey> {
523     void operator()(aiVector3D &out, const aiVectorKey &a,
524             const aiVectorKey &b, ai_real d) const {
525         Interpolator<aiVector3D> ipl;
526         ipl(out, a.mValue, b.mValue, d);
527     }
528 }; // ! Interpolator <aiVectorKey>
529 
530 template <>
531 struct Interpolator<aiQuatKey> {
532     void operator()(aiQuaternion &out, const aiQuatKey &a,
533             const aiQuatKey &b, ai_real d) const {
534         Interpolator<aiQuaternion> ipl;
535         ipl(out, a.mValue, b.mValue, d);
536     }
537 }; // ! Interpolator <aiQuatKey>
538 
539 template <>
540 struct Interpolator<aiMeshKey> {
541     void operator()(unsigned int &out, const aiMeshKey &a,
542             const aiMeshKey &b, ai_real d) const {
543         Interpolator<unsigned int> ipl;
544         ipl(out, a.mValue, b.mValue, d);
545     }
546 }; // ! Interpolator <aiQuatKey>
